WITH cleaned AS (SELECT *, LOWER(page) AS page_lower FROM web_events WHERE event_time >= TO_DATE('2023-10-01') AND session_id IN (21, 24, 29)), base AS (SELECT id, session_id, event_type, page_lower, ROUND(duration_sec * 0.9, 2) AS duration_sec_scaled, ROUND(duration_sec, 1) AS duration_sec_rounded, COALESCE(page, 'OTHER') AS resolved_page FROM cleaned WHERE event_time >= TO_TIMESTAMP('2023-04-23 18:00:00') AND page IN ('/checkout', '/home')), enriched AS (SELECT e.*, b.country, b.browser, b.device FROM base e LEFT JOIN sessions b ON e.session_id = b.id), enriched_web_events AS (SELECT s.*, b.country AS session_country, b.browser AS session_browser FROM enriched s INNER JOIN sessions b ON s.session_id = b.id) SELECT id, session_id, event_type, page_lower, duration_sec_scaled, duration_sec_rounded, country, browser, device FROM enriched_web_events
